import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { setupGlobalSkills } from "./setup-global-skills.js";

vi.mock("node:fs", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:fs")>();
  return {
    ...actual,
    existsSync: vi.fn(),
    mkdirSync: vi.fn(),
    rmSync: vi.fn(),
    readdirSync: vi.fn(),
    lstatSync: vi.fn(),
    copyFileSync: vi.fn(),
  };
});

vi.mock("node:os", () => ({
  homedir: vi.fn(() => "/home/testuser"),
}));

describe("setupGlobalSkills", () => {
  let emitted: Array<Record<string, unknown>>;
  let emit: (event: Record<string, unknown>) => void;

  beforeEach(() => {
    emitted = [];
    emit = (event) => {
      emitted.push(event);
    };
    vi.clearAllMocks();
    vi.mocked(os.homedir).mockReturnValue("/home/testuser");
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("reads from claude/technical_skills and claude/workflow_skills — not root paths", () => {
    vi.mocked(fs.existsSync).mockImplementation((p) => {
      const ps = String(p);
      // global skills dir does not exist yet; source dirs exist
      return (
        ps.includes("claude/technical_skills") ||
        ps.includes("claude/workflow_skills")
      );
    });
    vi.mocked(fs.readdirSync).mockReturnValue([]);

    setupGlobalSkills("/workspace", "/workflow", emit);

    const existsCalls = vi.mocked(fs.existsSync).mock.calls.map((c) => String(c[0]));
    expect(existsCalls.some((p) => p.includes("claude/technical_skills"))).toBe(true);
    expect(existsCalls.some((p) => p.includes("claude/workflow_skills"))).toBe(true);
    // must NOT probe old root-level paths
    expect(existsCalls.some((p) => /\/workflow\/technical_skills$/.test(p))).toBe(false);
    expect(existsCalls.some((p) => /\/workflow\/workflow_skills$/.test(p))).toBe(false);
  });

  it("reads from workflow/claude/technical_skills with the exact joined path", () => {
    vi.mocked(fs.existsSync).mockReturnValue(false);

    setupGlobalSkills("/workspace", "/workflow", emit);

    const existsCalls = vi.mocked(fs.existsSync).mock.calls.map((c) => String(c[0]));
    expect(
      existsCalls.some((p) => p === path.join("/workflow", "claude", "technical_skills")),
    ).toBe(true);
    expect(
      existsCalls.some((p) => p === path.join("/workflow", "claude", "workflow_skills")),
    ).toBe(true);
  });

  it("recreates ~/.claude/skills dir each run (removes then creates)", () => {
    const globalSkillsDir = path.join("/home/testuser", ".claude", "skills");
    vi.mocked(fs.existsSync).mockImplementation((p) => String(p) === globalSkillsDir);
    vi.mocked(fs.readdirSync).mockReturnValue([]);

    setupGlobalSkills("/workspace", "/workflow", emit);

    expect(fs.rmSync).toHaveBeenCalledWith(globalSkillsDir, { recursive: true, force: true });
    expect(fs.mkdirSync).toHaveBeenCalledWith(globalSkillsDir, { recursive: true });
  });

  it("does not call rmSync when global skills dir does not exist yet", () => {
    vi.mocked(fs.existsSync).mockReturnValue(false);

    setupGlobalSkills("/workspace", "/workflow", emit);

    expect(fs.rmSync).not.toHaveBeenCalled();
  });

  it("copies skill subdirectories from source dirs to global skills dir", () => {
    const globalSkillsDir = path.join("/home/testuser", ".claude", "skills");
    const techSkillsDir = path.join("/workflow", "claude", "technical_skills");

    vi.mocked(fs.existsSync).mockImplementation((p) => {
      const ps = String(p);
      return ps === techSkillsDir || ps.includes("backend-engineer");
    });
    vi.mocked(fs.readdirSync).mockImplementation((p) => {
      if (String(p) === techSkillsDir) return ["backend-engineer"] as unknown as fs.Dirent[];
      return [];
    });
    vi.mocked(fs.lstatSync).mockImplementation((p) => {
      return { isDirectory: () => true, isFile: () => false, isSymbolicLink: () => false } as fs.Stats;
    });

    setupGlobalSkills("/workspace", "/workflow", emit);

    const mkdirCalls = vi.mocked(fs.mkdirSync).mock.calls.map((c) => String(c[0]));
    expect(
      mkdirCalls.some((p) => p === path.join(globalSkillsDir, "backend-engineer")),
    ).toBe(true);
  });

  it("emits skill_copy_warn when a skill copy fails", () => {
    const techSkillsDir = path.join("/workflow", "claude", "technical_skills");

    vi.mocked(fs.existsSync).mockImplementation((p) => String(p) === techSkillsDir);
    vi.mocked(fs.readdirSync).mockImplementation((p) => {
      if (String(p) === techSkillsDir) return ["broken-skill"] as unknown as fs.Dirent[];
      return [];
    });
    vi.mocked(fs.lstatSync).mockImplementation(() => {
      throw new Error("permission denied");
    });

    setupGlobalSkills("/workspace", "/workflow", emit);

    expect(emitted.some((e) => e["type"] === "skill_copy_warn")).toBe(true);
  });
});

